<?php
declare(strict_types=1);
require __DIR__.'/includes/cms-boot.php';
use App\Db;
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);
if(!$id){header('Location: /admin/customers.php');exit;}
$db=Db::pdo();$q=$db->prepare('SELECT c.id,c.email,c.created_at,a.recipient,a.phone,a.address,a.neighborhood,a.reference_point FROM customer_accounts c LEFT JOIN customer_addresses a ON a.customer_id=c.id WHERE c.id=?');$q->execute([$id]);$customer=$q->fetch();
if(!$customer){http_response_code(404);adm_start('Cliente não encontrado','customers');?><h1 class="page-title">Cliente não encontrado</h1><a href="/admin/customers.php">Voltar aos clientes</a><?php adm_end();exit;}
$q=$db->prepare('SELECT id,status,quantity,total_cents,payment_status,created_at FROM lunch_orders WHERE customer_id=? ORDER BY id DESC LIMIT 50');$q->execute([$id]);$orders=$q->fetchAll();$labels=['pending'=>'Novo pedido','accepted'=>'Aceito','preparing'=>'Em preparação','out_for_delivery'=>'Saindo para entrega','delivered'=>'Entregue','cancelled'=>'Cancelado'];
adm_start('Detalhes do cliente','customers');?>
<div class="mb-4"><a class="small" href="/admin/customers.php"><i class="bi bi-arrow-left"></i> Voltar aos clientes</a><h1 class="page-title"><?=adm_h($customer['recipient']?:'Cliente #'.$customer['id'])?></h1><p class="page-subtitle"><?=adm_h($customer['email'])?></p></div><div class="row g-4"><div class="col-lg-5"><section class="content-card p-4"><h2 class="h5">Dados cadastrados</h2><dl class="customer-details"><dt>E-mail</dt><dd><?=adm_h($customer['email'])?></dd><dt>Telefone</dt><dd><?=adm_h($customer['phone']?:'Não informado')?></dd><dt>Endereço padrão</dt><dd><?=adm_h($customer['address']?:'Não informado')?></dd><dt>Bairro</dt><dd><?=adm_h($customer['neighborhood']?:'Não informado')?></dd><dt>Referência</dt><dd><?=adm_h($customer['reference_point']?:'Não informada')?></dd><dt>Cadastro</dt><dd><?=adm_h(date('d/m/Y H:i',strtotime($customer['created_at'])))?></dd></dl></section></div><div class="col-lg-7"><section class="content-card"><div class="content-heading"><h2>Histórico de quentinhas</h2></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido</th><th>Status</th><th>Quantidade</th><th>Valor</th><th>Data</th></tr></thead><tbody><?php foreach($orders as $order):?><tr><td>#<?=adm_h($order['id'])?></td><td><?=adm_h($labels[$order['status']]??$order['status'])?></td><td><?=adm_h($order['quantity'])?></td><td>R$ <?=number_format($order['total_cents']/100,2,',','.')?></td><td><?=adm_h(date('d/m/Y H:i',strtotime($order['created_at'])))?></td></tr><?php endforeach;?></tbody></table><?php if(!$orders):?><div class="empty-state">Nenhum pedido vinculado a esta conta.</div><?php endif;?></div></section></div></div><?php adm_end();